const fs = require('node:fs'), path = require('node:path'), Module = require('node:module'), assert = require('node:assert/strict');
const config = path.resolve('conf/stm_config.json');
(async () => {
  const {AlertsSettings} = require('./fe/server/dist/alertsSettings.js');
  const result = await new AlertsSettings(config).get();
  const file = path.resolve('fe/server/dist/alertsSettings.js');
  const validator = new Module(file, module);
  validator.filename=file; validator.paths=Module._nodeModulePaths(path.dirname(file));
  validator._compile(fs.readFileSync(file,'utf8')+'\nexports.check = validateDocument;',file);
  validator.exports.check(result.document,result.metrics,result.protocols);
  let conditions=0;
  for (const binding of result.document.bindings) {
    const policy=result.document.policies.find(p=>p.id===binding.policy_id);
    const rules=policy.conditions.map(r=>({...r,...binding.adjustments?.[r.id]})).concat(binding.additional_conditions||[]);
    const silence=rules.find(r=>r.id==='availability');
    assert.equal(silence.type,'threshold'); assert.equal(silence.metric,'packet_count.window');
    assert.equal(silence.error_threshold,1); assert.equal(silence.trigger_after_sec,5);
    for (const r of rules) {
      assert(result.metrics.some(m=>m.key===r.metric));
      if (['loss','duplicate','reorder'].includes(r.id)) { assert.equal(r.error_threshold,0); assert.equal(r.trigger_after_sec,0); }
    }
    conditions += rules.length;
  }
  console.log(`Alert config load/validation OK: ${result.document.policies.length} policies, ${result.document.bindings.length} bindings, ${conditions} effective conditions; window-based silence enabled.`);
})().catch(e=>{console.error(e);process.exitCode=1;});
